function Rating_popup()
{
	if(window.confirm("## Kindly follow below Instructions for Auto Rating : \r\n 1. Check Booking Creation for NAC, If NAC is available select CMDT & A/Customer as per Booking NAC. \r\n 2. Select Rate as per NAC. \r\n 3. If no NAC, then select Rate as per cargo description. \r\n 4. If not found as per cargo description, then FAK Straight/ Consolidation. \r\n 5. If no rates as per above condition, then check Route details. \r\n 6. Then check Route / CMDT/Special Note (Lane/VVD/Validity/NAC/ICD/GOH). \r\n 7. Check Gross weight.\r\n 8. For US/CA Shipment: Shipper or Consignee should match Contract Holders or Affiliates.\r\n 9. For other than US/CA Shipment: Shipper, Consignee or Forwarder should match Contract Holder or Affiliates.\r\n 10. For Non-FMC related Shipments: Contract Holder match is no longer required for bookings from ONE Quote.\r\n 11. For FMC related Shipments: Contract Holder match is required for bookings from ONE Quote.\r\n 12. (Matching rule is same with Non-Quote bookings.)"))
	{

	}
}

