function custAddressPrintTick() 
{
    try 
	{
        const checks = [
            { seq: "sh_cust_nm", flag: "sh_addr_prn_flg", msg: "Shipper Address Print tick is missing" },
            { seq: "cn_cust_nm", flag: "cn_addr_prn_flg", msg: "Consignee Address Print tick is missing" },
            { seq: "nf_cust_nm", flag: "nf_addr_prn_flg", msg: "Notify Address Print tick is missing" },
            { seq: "an_cust_nm", flag: "an_addr_prn_flg", msg: "A/Notify Address Print tick is missing" }
        ];

        let missing = [];

        checks.forEach(item => {
            const seqVal = (document.getElementById(item.seq)?.value || "").trim();
            const flag = document.getElementById(item.flag)?.checked;

            // Special rule for Notify Party
            if (item.seq === "nf_cust_nm") 
			{
                // Skip if "same as consignee" conditions
                if (seqVal === "SAME AS CONSIGNEE" || seqVal === "SAME AS CNEE") 
				{
                    return; // don't validate this case
                }
            }

            if (seqVal !== "" && !flag) 
			{
                missing.push(item.msg);
            }
        });

        if (missing.length > 0) 
		{
            alert(missing.join("\n"));
            return false;
        }
        return true;
    } 
	catch (err) 
	{
        console.error("Error in custAddressPrintTick:", err);
        return false;
    }
}

