function TAO_Garlic_Prohibited()
{
	try
	{
		var marks = document.getElementsByName("mk_desc")[0].value;
		var longdesc = document.getElementsByName("dg_cmdt_desc")[0].value;
		var pod = document.getElementsByName("pod_cd")[0].value.substring(0,2);
		var del = document.getElementsByName("del_cd")[0].value.substring(0,2);
		var bl = document.getElementsByName("bkg_no")[0].value.substring(0,2);
		var flag = 0;
		
		if(bl == "TA")
		{
			if(pod == "BR" || del == "BR")
			{
				if(marks.includes("GARLIC"))
				{
					flag = 1;
				}
				if(longdesc.includes("GARLIC"))
				{
					flag = 1;
				}
				if(flag == 1)
				{
					window.alert("Prohibited Keyword 'Garlic' found in M&D Tab.");
				}
			}
		}
	}
	catch(err)
	{
		
	}
	
	try 
	{
		const blPrefix = document.getElementById("bkg_no").value;
		const pod = document.getElementById("pod_cd").value;
		const cnName = document.getElementById("cn_cust_nm").value.replaceAll("\n","").trim();
		const cnAdd = document.getElementById("cn_cust_addr").value.replaceAll("\n","").trim();

		const keywords = [
			"MAGALUSI COMERCIO DE GENEROS ALIMENTICIOS LTDA",
			"MAGALUSI COMERCIO DE GENEROSALIMENTICIOS LTDA",
			"GLOBAL FOODS IMPORTACAO E EXPORTACAO LTDA R",
			"GLOBAL FOODS IMPORTACAO EEXPORTACAO LTDA R",
			"ML COMERCIO DE PRODUTOS ALIMENTICIOS LTDA",
			"ML COMERCIO DE PRODUTOSALIMENTICIOS LTDA",
			"ADRIANA PESSOA"
		];

		if (blPrefix.startsWith("TA") && pod.startsWith("BR")) 
		{
			const matchFound = keywords.some(keyword =>
				cnName.includes(keyword) || cnAdd.includes(keyword)
			);

			if (matchFound) 
			{
				alert("As per TM approval, garlic commodity is acceptable without LOI for reefer shipments");
			}
		}
	} 
	catch (err) 
	{
		
	}

}